absl::optional<Json> ValidateAndWrapAuditLoggerConfig(
    absl::string_view name, Json json_config, ValidationErrors* errors) {
  auto result = AuditLoggerRegistry::ParseConfig(name, json_config);
  if (!result.ok()) {
    errors->AddError(result.status().message());
    return Json();
  }
  return Json::FromObject({{std::string(name), std::move(json_config)}});
}

}  // namespace

auto result = MatchMutable(
    &extension->value,
    [this, &context, &extension, errors](absl::string_view* serialized_value)
        -> absl::optional<Json> {
      auto config_factory_it =
          audit_logger_config_factories_.find(extension->type);
      if (config_factory_it == audit_logger_config_factories_.end()) {
        return absl::nullopt;
      }
      auto json_config = Json::FromObject(
          config_factory_it->second->ConvertXdsAuditLoggerConfig(
              context, *serialized_value, errors));
      return ValidateAndWrapAuditLoggerConfig(
          config_factory_it->second->name(), std::move(json_config), errors);
    },
    [&extension, errors](Json* json) -> absl::optional<Json> {
      if (!AuditLoggerRegistry::FactoryExists(extension->type)) {
        return absl::nullopt;
      }
      return ValidateAndWrapAuditLoggerConfig(extension->type,
                                             std::move(*json), errors);
    });
if (result.has_value()) return std::move(*result);

